WITH ranked AS (SELECT id, dept_id, manager_id, job_title, hire_date, is_remote FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_id, job_title ORDER BY hire_date DESC NULLS FIRST, id ASC) AS rn FROM employees) ranked WHERE rn = 1) SELECT s.id, s.manager_id, s.hire_date, s.is_remote, (SELECT MIN(t2.salary) FROM employees t2 WHERE t2.manager_id = s.manager_id) AS min_employee_salary FROM ranked s ORDER BY id DESC NULLS FIRST LIMIT 5
